(function(){'use strict';
var KEY='welog-direct-stickers-v1',sheet=document.getElementById('sheet'),controls=document.getElementById('controls');if(!sheet)return;
var selected=-1,drag=null,refreshing=false,renderQueued=false;
function read(){try{var a=JSON.parse(localStorage.getItem(KEY)||'[]');return Array.isArray(a)?a:[]}catch(e){return[]}}
function persist(a,notify){try{localStorage.setItem(KEY,JSON.stringify(a))}catch(e){}if(notify!==false)window.dispatchEvent(new CustomEvent('welog-stickers-changed'))}
function norm(s){s=s||{};return{src:s.src||'',x:isFinite(+s.x)?+s.x:50,y:isFinite(+s.y)?+s.y:50,w:isFinite(+s.w)?+s.w:120,rot:isFinite(+s.rot)?+s.rot:0,locked:!!s.locked}}
function layer(){var l=sheet.querySelector('.direct-sticker-layer');if(!l){l=document.createElement('div');l.className='direct-sticker-layer';sheet.appendChild(l)}return l}
function render(){if(refreshing||drag)return;refreshing=true;var a=read().map(norm),l=layer();l.innerHTML='';a.forEach(function(s,i){var el=document.createElement('div');el.className='direct-sticker sticker-v2'+(s.locked?' is-locked':'')+(i===selected?' is-selected':'');el.dataset.i=i;el.style.left=s.x+'%';el.style.top=s.y+'%';el.style.width=s.w+'px';el.style.transform='translate(-50%,-50%) rotate('+s.rot+'deg)';el.innerHTML='<img draggable="false"><button class="st-v2-lock" type="button" title="잠금">'+(s.locked?'🔒':'🔓')+'</button><button class="st-v2-del" type="button" title="삭제">×</button><i class="st-v2-resize" title="크기 조절"></i>';el.querySelector('img').src=s.src;l.appendChild(el);bind(el,i)});refreshing=false;renderList()}
function bind(el,i){el.addEventListener('click',function(e){if(e.target.closest('button,.st-v2-resize'))return;e.stopPropagation();if(selected!==i){selected=i;render()}});el.addEventListener('pointerdown',function(e){if(e.target.closest('button'))return;var a=read(),s=norm(a[i]);if(s.locked)return;var mode=e.target.closest('.st-v2-resize')?'resize':'move';selected=i;drag={i:i,mode:mode,x:e.clientX,y:e.clientY,base:s,pid:e.pointerId,el:el,next:null,raf:0};el.classList.add('is-selected','is-dragging');e.preventDefault();e.stopPropagation();el.setPointerCapture&&el.setPointerCapture(e.pointerId)});el.addEventListener('pointermove',function(e){if(!drag||drag.i!==i||drag.pid!==e.pointerId)return;var r=sheet.getBoundingClientRect(),dx=e.clientX-drag.x,dy=e.clientY-drag.y,s=Object.assign({},drag.base);if(drag.mode==='move'){s.x=Math.max(0,Math.min(100,drag.base.x+dx/r.width*100));s.y=Math.max(0,Math.min(100,drag.base.y+dy/r.height*100))}else{s.w=Math.max(24,Math.min(700,drag.base.w+dx))}drag.next=s;if(!drag.raf)drag.raf=requestAnimationFrame(function(){if(!drag||!drag.next)return;var q=drag.next;drag.el.style.left=q.x+'%';drag.el.style.top=q.y+'%';drag.el.style.width=q.w+'px';drag.raf=0})});function finish(e){if(!drag||drag.i!==i)return;var d=drag;if(d.raf)cancelAnimationFrame(d.raf);var a=read();a[i]=norm(d.next||d.base);drag=null;d.el.classList.remove('is-dragging');persist(a,false);renderList()}el.addEventListener('pointerup',finish);el.addEventListener('pointercancel',finish);el.querySelector('.st-v2-lock').onclick=function(e){e.stopPropagation();var a=read();a[i]=norm(a[i]);a[i].locked=!a[i].locked;persist(a,false);selected=i;render()};el.querySelector('.st-v2-del').onclick=function(e){e.stopPropagation();var a=read();a.splice(i,1);persist(a,false);selected=-1;render()}}
function managerHost(){if(!controls)return null;var existing=controls.querySelector('.sticker-manager-v2');if(existing)return existing;var hint=controls.querySelector('[data-sticker-upload]')||Array.from(controls.querySelectorAll('*')).find(function(n){return (n.textContent||'').trim()==='스티커'});if(!hint)return null;var box=document.createElement('section');box.className='sticker-manager-v2';box.innerHTML='<div class="sticker-manager-head"><b>스티커 목록</b><span>현재 시트의 스티커를 모두 관리합니다.</span></div><div class="sticker-manager-list"></div>';var parent=hint.closest('.control-card,.section,.panel-section')||hint.parentElement||controls;parent.insertAdjacentElement('afterend',box);return box}
function renderList(){var box=managerHost();if(!box)return;var list=box.querySelector('.sticker-manager-list'),a=read().map(norm);if(!a.length){list.innerHTML='<p class="sticker-empty">붙여진 스티커가 없습니다.</p>';return}list.innerHTML='';a.forEach(function(s,i){var row=document.createElement('div');row.className='sticker-list-row'+(i===selected?' is-selected':'');row.innerHTML='<button class="sticker-thumb" type="button"><img></button><div class="sticker-row-info"><b>스티커 '+(i+1)+'</b><span>'+(Math.round(s.w))+'px · '+(s.locked?'잠금':'편집 가능')+'</span></div><button class="sticker-row-lock" type="button">'+(s.locked?'🔒':'🔓')+'</button><button class="sticker-row-del" type="button">×</button>';row.querySelector('img').src=s.src;row.querySelector('.sticker-thumb').onclick=function(){selected=i;render()};row.querySelector('.sticker-row-lock').onclick=function(){var q=read();q[i]=norm(q[i]);q[i].locked=!q[i].locked;persist(q,false);selected=i;render()};row.querySelector('.sticker-row-del').onclick=function(){var q=read();q.splice(i,1);persist(q,false);if(selected===i)selected=-1;else if(selected>i)selected--;render()};list.appendChild(row)})}
document.addEventListener('click',function(e){if(!e.target.closest('.direct-sticker,.sticker-manager-v2')){selected=-1;sheet.querySelectorAll('.sticker-v2.is-selected').forEach(function(n){n.classList.remove('is-selected')})}},true);
function queueRender(){if(drag||renderQueued)return;renderQueued=true;requestAnimationFrame(function(){renderQueued=false;render()})}
window.addEventListener('welog-stickers-changed',queueRender);window.addEventListener('welog-stickers-restored',queueRender);
document.addEventListener('change',function(e){if(e.target.matches('[data-sticker-upload]'))setTimeout(queueRender,80)},true);document.addEventListener('click',function(e){if(e.target.closest('[data-sticker-add],#tabs'))setTimeout(queueRender,80)},true);
new MutationObserver(function(){if(refreshing||drag)return;var old=sheet.querySelector('.direct-sticker .st-toolbar');if(old||(!sheet.querySelector('.sticker-v2')&&read().length))queueRender();if(controls&&!renderQueued)requestAnimationFrame(renderList)}).observe(document.body,{childList:true,subtree:true});
render();
})();